import sys
import json
import xml.etree.ElementTree as ET
from datetime import datetime
import argparse
import time

def parse_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    services = {}
    for service in root.findall('service'):
        name = service.get('name')
        limit = int(service.get('limit'))
        services[name] = limit
    return services

def load_state(json_path):
    if not json_path:
        return {}
    with open(json_path, 'r') as f:
        return json.load(f)

def save_state(json_path, state):
    with open(json_path, 'w') as f:
        json.dump(state, f)

def token_bucket(service_name, limit, state):
    current_time = time.time()
    service_state = state.get(service_name, {'tokens': limit, 'last_refill': current_time})
    tokens = service_state['tokens']
    last_refill = service_state['last_refill']

    if current_time - last_refill >= 60:
        service_state['tokens'] = min(limit, tokens + limit)
        service_state['last_refill'] = current_time
    else:
        service_state['tokens'] = min(limit, tokens + (limit / 60) * (current_time - last_refill))

    return service_state['tokens'] >= 1

def process_input(xml_path, json_path, token_list):
    services = parse_config(xml_path)
    state = load_state(json_path)
    allowed_services = set(token_list.split(',')) if token_list else set()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name = line
        if name not in services:
            print(f"UNKNOWN {name}")
            continue
        if name not in allowed_services:
            print(f"UNAUTHORIZED {name}")
            continue
        if token_bucket(name, services[name], state):
            print(f"ALLOW {name}")
            state[name] = {'tokens': state[name]['tokens'] - 1, 'last_refill': state[name]['last_refill']}
        else:
            print(f"DENY {name}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('xml_path', help='Path to the XML configuration file')
    parser.add_argument('json_path', help='Path to the JSON state file')
    args = parser.parse_args()

    token_line = sys.stdin.readline().strip()
    process_input(args.xml_path, args.json_path, token_line)

    # Save state after processing all input
    save_state(args.json_path, state)

if __name__ == "__main__":
    state = {}
    main()

import sys
import argparse
import xml.etree.ElementTree as ET
import json
import time
from datetime import datetime

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    return {attr: int(root.attrib[attr]) for attr in ('name', 'limit')}

def parse_input():
    services_line = sys.stdin.readline().strip().split(',')
    requested_service = sys.stdin.readline().strip()
    return services_line, requested_service

def load_state(state_path):
    try:
        with open(state_path, 'r') as f:
            state = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        state = {}
    return state

def save_state(state_path, state):
    with open(state_path, 'w') as f:
        json.dump(state, f)

def calculate_permit_count(service_limit, last_refill, current_time):
    if last_refill is None:
        return service_limit
    time_diff = current_time - last_refill
    permits = service_limit + (time_diff // 60) * service_limit
    return min(permits, service_limit)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('xml_config', type=str)
    parser.add_argument('json_state', type=str)
    args = parser.parse_args()

    config = parse_xml_config(args.xml_config)
    services_line, requested_service = parse_input()

    if requested_service not in config['name']:
        print(f"UNKNOWN {requested_service}")
        return

    if requested_service not in services_line:
        print(f"UNAUTHORIZED {requested_service}")
        return

    state = load_state(args.json_state)
    service_config = config
    current_time = time.time()

    if requested_service not in state:
        state[requested_service] = {
            'tokens': service_config['limit'],
            'last_refill': current_time
        }
    else:
        state[requested_service]['last_refill'] = current_time

    permit_count = calculate_permit_count(
        service_config['limit'],
        state[requested_service]['last_refill'],
        current_time
    )

    if permit_count >= 1:
        state[requested_service]['tokens'] = permit_count - 1
        print(f"ALLOW {requested_service}")
    else:
        print(f"DENY {requested_service}")

    state[requested_service]['last_refill'] = current_time
    save_state(args.json_state, state)

if __name__ == "__main__":
    main()
